(()=>{'use strict';if(window.__nexleyForms)return;window.__nexleyForms=true;const cfg=window.nexleyFormsConfig ||{endpoint:'/wp-json/nexley/v1/submit',i18n:{submitting:'Sending...',generic_error:'Something went wrong. Please check your inputs.',network_error:'Network connection error. Please try again.'}};function initTimeTrap(form){const tt=form.querySelector('.nexley-forms__tt');if(tt && !tt.value){tt.value=String(Date.now())}}document.addEventListener('focusin',(e)=>{const form=e.target.closest('.nexley-forms');if(form)initTimeTrap(form)},{passive:true,once:false});document.addEventListener('submit',async(e)=>{const form=e.target.closest('.nexley-forms');if(!form)return;e.preventDefault();initTimeTrap(form);const statusEl=form.querySelector('.nexley-forms__status');const submitBtn=form.querySelector('.nexley-forms__submit');const origBtnText=submitBtn ?(submitBtn.textContent || submitBtn.value):'';form.querySelectorAll('[aria-invalid="true"],.is-invalid').forEach((el)=>{el.removeAttribute('aria-invalid');el.classList.remove('is-invalid')});if(form.checkValidity && !form.checkValidity()){if(form.reportValidity)form.reportValidity();return}form.classList.add('is-submitting');if(submitBtn){submitBtn.disabled=true;if(cfg.i18n && cfg.i18n.submitting){if(submitBtn.tagName==='INPUT')submitBtn.value=cfg.i18n.submitting;else submitBtn.textContent=cfg.i18n.submitting}}if(statusEl){statusEl.className='nexley-forms__status is-loading';statusEl.textContent=cfg.i18n.submitting}const formData=new FormData(form);const endpoint=form.dataset.endpoint || form.getAttribute('action')|| cfg.endpoint;try{const res=await fetch(endpoint,{method:'POST',body:formData,headers:{Accept:'application/json'}});const data=await res.json().catch(()=>null);if(res.ok && data && data.success){form.classList.remove('is-submitting');form.classList.add('is-submitted-success');if(statusEl){statusEl.className='nexley-forms__status is-success';statusEl.textContent=data.message || 'Thank you! Your message has been sent successfully.'}form.reset();if(data.redirect_url){window.location.href=data.redirect_url;return}form.dispatchEvent(new CustomEvent('nexley:form:success',{bubbles:true,detail:data}))}else{form.classList.remove('is-submitting');form.classList.add('is-submitted-error');const msg=(data && data.message)? data.message:cfg.i18n.generic_error;if(statusEl){statusEl.className='nexley-forms__status is-error';statusEl.textContent=msg}if(data && data.errors && typeof data.errors==='object'){let firstInvalid=null;for(const[key,val]of Object.entries(data.errors)){const ctrl=form.querySelector(`[name="${key}"],[name="${key}[]"]`);if(ctrl){ctrl.setAttribute('aria-invalid','true');ctrl.classList.add('is-invalid');if(!firstInvalid)firstInvalid=ctrl}}if(firstInvalid && firstInvalid.focus)firstInvalid.focus()}form.dispatchEvent(new CustomEvent('nexley:form:error',{bubbles:true,detail:data ||{message:msg}}))}}catch(err){form.classList.remove('is-submitting');form.classList.add('is-submitted-error');if(statusEl){statusEl.className='nexley-forms__status is-error';statusEl.textContent=cfg.i18n.network_error}form.dispatchEvent(new CustomEvent('nexley:form:error',{bubbles:true,detail:{error:err}}))}finally{if(submitBtn){submitBtn.disabled=false;if(submitBtn.tagName==='INPUT')submitBtn.value=origBtnText;else submitBtn.textContent=origBtnText}}},false)})();